/**
 * Shared resource placement utilities used by both initial generation and age transitions.
 * Contains tile classification, blue noise window building, landmass eligibility, and
 * per-plot resource validation logic.
 * @packageDocumentation
 */

import * as globals from "#base/maps/map-globals.js";
import { profileScope } from "#base/scripts/profiling.js";
import { sampleBlueNoise } from "#base/scripts/utils/blue-noise.js";

// Developer-only verbose logging toggle.
export const VERBOSE_LOGGING = true;

// A dense 0-based index into GameInfo.Resources (i.e. resourceDef.$index).
export type ResourceIndex = number;
// A hashed resource identifier (i.e. resourceDef.$hash).
export type ResourceHash = number;

// Number of landmass groups resources are partitioned into.
// Currently 2 (the hemisphere split). If this becomes map or age-dependent,
// compute it once in buildPlacementContext and store in the returned context.
export const NUM_LANDMASS_GROUPS = 2;

// Consider placing these in a database at some point to allow for easy mod overrides.
export const DENSITY_TARGET = 0.15;
export const MAX_DENSITY = 0.5;

// Flag bit in packed window type field indicating the resource requires land adjacency.
const ADJACENT_TO_LAND_FLAG = 0x8000;
// Mask to extract resource type index from packed window type field.
const RESOURCE_TYPE_MASK = 0x7fff;

// ===========================================================================================
// Tile Classification
// ===========================================================================================

const TERRAIN_BITS = 4;
const BIOME_BITS = 4;
const FEATURE_BITS = 6;
const TERRAIN_MASK = (1 << TERRAIN_BITS) - 1;
const BIOME_MASK = (1 << BIOME_BITS) - 1;
const FEATURE_MASK = (1 << FEATURE_BITS) - 1;
const TERRAIN_SHIFT = BIOME_BITS + FEATURE_BITS;
const BIOME_SHIFT = FEATURE_BITS;
const FEATURE_SHIFT = 0;

// Number of bits used by tileClassId.
export const TILE_CLASS_ID_BITS = TERRAIN_BITS + BIOME_BITS + FEATURE_BITS;
// One past the largest valid tileClassId (also the required size of tile-group indexed arrays).
export const TILE_CLASS_ID_MAX = 1 << TILE_CLASS_ID_BITS;

// Encodes the tile properties that partition tiles into blue noise window groups.
// terrain/biome/feature form an exclusive partition (every tile belongs to exactly one group).
export interface TileClass {
	terrain: TerrainType;
	biome: BiomeType;
	feature: FeatureType;
}

// Indirection that compresses the sparse tileClassId space into a dense 8-bit index.
const tileGroupBits = 8;
const tileIndexMax = (1 << tileGroupBits) - 1;
const tileIdToIndex = new Uint8Array(TILE_CLASS_ID_MAX);
let numTileGroups = 0;
for (const validBiome of GameInfo.Resource_ValidBiomes) {
	const rawId = tileClassIdFromValidBiome(validBiome);
	if (rawId === undefined) continue;
	if (tileIdToIndex[rawId] !== 0) continue; // tuple already assigned
	numTileGroups++;
	if (numTileGroups > tileIndexMax) {
		throw new Error(
			`Resource_ValidBiomes has too many unique tile-group tuples (${numTileGroups} >= ${tileIndexMax})`,
		);
	}
	tileIdToIndex[rawId] = numTileGroups;
}
export const NUM_TILE_GROUPS = numTileGroups + 1; // +1 for the 0 = no-resource group

// Translates a raw tileClassId to a dense 1..NUM_TILE_GROUPS-1 index, or 0 if the tuple has no resources.
export function getDenseTileGroupId(rawTileId: number): number {
	return tileIdToIndex[rawTileId];
}

// Creates a single numeric key from terrain/biome/feature
// Layout: terrain[13:10] | biome[9:6] | feature[5:0]. Range is 0...TILE_CLASS_ID_MAX - 1
export function getTileClassId(terrain: number, biome: number, feature: number): number {
	return (
		((terrain & TERRAIN_MASK) << TERRAIN_SHIFT) |
		((biome & BIOME_MASK) << BIOME_SHIFT) |
		((feature & FEATURE_MASK) << FEATURE_SHIFT)
	);
}

// Returns a composite key with a small extra 4 bit landmass id packed into the high bits.
export function getLandmassTileClassGroupId(denseId: number, extra: number): number {
	return denseId | ((extra & 0xf) << tileGroupBits);
}

// Returns the TileClass for the given map coordinates.
export function getTileClass(x: number, y: number): TileClass {
	return {
		terrain: GameplayMap.getTerrainType(x, y),
		biome: GameplayMap.getBiomeType(x, y),
		feature: GameplayMap.getFeatureType(x, y),
	};
}

// Returns the TileId for the given map coordinates.
export function getTileId(x: number, y: number): number {
	const terrain = GameplayMap.getTerrainType(x, y);
	const biome = GameplayMap.getBiomeType(x, y);
	const feature = GameplayMap.getFeatureType(x, y);
	return getTileClassId(terrain as number, biome as number, feature as number);
}

// Creates a tile class from a tile id (mostly for debugging)
export function tileClassFromId(tileId: number): TileClass {
	return {
		terrain: (tileId >> TERRAIN_SHIFT) & TERRAIN_MASK,
		biome: (tileId >> BIOME_SHIFT) & BIOME_MASK,
		feature: (tileId >> FEATURE_SHIFT) & FEATURE_MASK,
	};
}

// Returns whether a tile is a coast/marine tile adjacent to land.
export function isCoastalAdjacentToLand(x: number, y: number, tc: TileClass): boolean {
	return (
		tc.terrain === globals.g_CoastTerrain &&
		tc.biome === globals.g_MarineBiome &&
		GameplayMap.isAdjacentToLand(x, y)
	);
}

// Resolves a Resource_ValidBiomes row to a numeric tileClassId by looking up terrain/biome/feature strings.
// Returns undefined if any lookup fails (e.g. unknown TerrainType).
export function tileClassIdFromValidBiome(validBiome: {
	TerrainType: string;
	BiomeType: string;
	FeatureType?: string;
}): number | undefined {
	const terrainDef = GameInfo.Terrains.find((t) => t.TerrainType === validBiome.TerrainType);
	const biomeDef = GameInfo.Biomes.find((b) => b.BiomeType === validBiome.BiomeType);
	if (!terrainDef || !biomeDef) return undefined;

	let feature: FeatureType;
	if (validBiome.FeatureType) {
		const featureDef = GameInfo.Features.find((f) => f.FeatureType === validBiome.FeatureType);
		if (!featureDef) return undefined;
		feature = featureDef.$index;
	} else {
		feature = FeatureTypes.NO_FEATURE;
	}

	return getTileClassId(terrainDef.$index, biomeDef.$index, feature as number);
}

// Returns a human-readable label for a TileClass (for debug logging).
export function tileClassLabel(tc: TileClass): string {
	const terrainName = GameInfo.Terrains[tc.terrain as number]?.TerrainType ?? `Unknown(${tc.terrain})`;
	const biomeName = GameInfo.Biomes[tc.biome as number]?.BiomeType ?? `Unknown(${tc.biome})`;
	let featureName: string;
	if (tc.feature === FeatureTypes.NO_FEATURE) {
		featureName = "NO_FEATURE";
	} else {
		featureName = GameInfo.Features[tc.feature as number]?.FeatureType ?? "";
	}
	return `${terrainName}/${biomeName}/${featureName}`;
}

// ===========================================================================================
// Landmass eligibility
// ===========================================================================================

// Determines whether a resource with a given assigned landmass group is allowed on a specific region.
// Regions are distributed round-robin across `numGroups`:
export function isResourceAllowedOnLandmass(assignedLandmass: number, regionId: number, numGroups: number): boolean {
	if (
		assignedLandmass === LandmassRegion.LANDMASS_REGION_ANY ||
		assignedLandmass === LandmassRegion.LANDMASS_REGION_DEFAULT ||
		regionId === 0
	)
		return true;
	if (assignedLandmass === LandmassRegion.LANDMASS_REGION_NONE) return false;
	const regionGroup = ((regionId - 1) % numGroups) + 1;
	return assignedLandmass === regionGroup;
}

// ===========================================================================================
// Map context building
// ===========================================================================================

// Immutable map data. Built once per map.
export interface ResourcePlacementContext {
	iWidth: number;
	iHeight: number;

	groupCount: Uint16Array;
	groupAdjCount: Uint16Array;
	groupRawId: Uint16Array;

	tileIdCache: Uint16Array;
	regionIdCache: Uint8Array;
	adjToLandCache: Uint8Array;
	maxPlayerRegion: number;
	nonOceanTileCount: number;

	regionCount: Uint16Array;
	regionAdjCount: Uint16Array;
	landmassEligible: Map<number, { count: number; adj: number }>;
}

// The set of resources being placed in a single run. Immutable after build.
export interface ResourceSet {
	// Flat list of resource $index values active in this run.
	activeResourceIndices: Uint16Array;
	// Per-resource weight, indexed by resource $index.
	resourceWeight: Float32Array;
	// Per-resource landmass group assignment, 0 = any, 1..numGroups = specific group.
	resourceAssignedLandmass: Uint8Array;
	// Pre-resolved biome/terrain/feature -> resource mappings.
	resolvedValidBiomes: ResolvedValidBiome[];
}

// Density metrics computed during windowing, consumed during placement.
export interface ResourceMetrics {
	// Expected placement count per resource $index.
	resourceDesiredCount: Float32Array;
	// Total eligible tile count per resource $index across all biomes.
	resourceEligibleTileCounts: Uint32Array;
	// Eligible tiles per (resource, landmass), size = numResources * maxPlayerRegion.
	resourceEligiblePerLandmass: Uint32Array;
	// Minimum-per-landmass per resource $index (0 = no minimum).
	resourceMinimumPerLandmass: Uint8Array;
}

// Packed blue noise window data in flat typed arrays.
export interface PackedBlueNoiseWindows {
	// Packed type field per window: bits 0-14 = resource index, bit 15 = AdjacentToLand.
	types: Uint16Array;
	// Window sizes in blue noise range [0, 65535].
	sizes: Uint16Array;
	// Start offset into types/sizes for each tile group (indexed by tileClassId index, 0..NUM_TILE_GROUPS).
	offsets: Uint16Array;
	// Number of windows for each tile group (indexed by tileClassId index, 0..NUM_TILE_GROUPS).
	counts: Uint8Array;
	// Maximum gap between each window for each tile group (indexed by tileClassId index, 0..NUM_TILE_GROUPS).
	maxGapSize: Uint16Array;
}

// The blue noise density plan. Output of windowing, input to placement.
export interface BlueNoisePlan {
	windows: PackedBlueNoiseWindows;
	metrics: ResourceMetrics;
}

export interface DensityConfig {
	// Target fraction of eligible tiles to receive resources (e.g. 0.14).
	densityTarget: number;
	// Per-resource density cap to prevent over-saturation (e.g. 0.5).
	maxDensity: number;
	// Per-resource minimum overrides (indexed by $index). Used during age transition
	// when some minimums have already been satisfied in an earlier phase.
	effectiveMinimums?: Uint16Array;
	// Optional per-(resource, tile group) density override. When present, replaces the
	// default weight-based split within a tile group. Key = resourceIdx * NUM_TILE_GROUPS + tileGroupId.
	// Missing entries default to 0 (no window).
	densityByResourceAndGroup?: Float32Array;
}

// Per-run placement options - hooks, offsets, filters. No computed data here.
export interface PlacementOptions {
	offsetX: number;
	offsetY: number;
	skipMask?: Uint8Array; // tile is skipped when non-zero
	// Optional callback for vetoing resource placement at a specific location.
	shouldPlaceResource?: (x: number, y: number, resourceIdx: ResourceIndex, regionId: number) => boolean;
	// Optional callback for logging/visualizing resource placement as it happens.
	onResourcePlaced?: (x: number, y: number, resourceIdx: ResourceIndex, regionId: number) => void;
}

const MAX_LANDMASS_REGIONS = 16;
const LANDMASS_BIT_SHIFT = 4;

// Scans the map and builds all tile classification caches needed for resource placement.
export function buildPlacementContext(iWidth: number, iHeight: number): ResourcePlacementContext {
	const totalTiles = iWidth * iHeight;
	const tileIdCache = new Uint16Array(totalTiles);
	const regionIdCache = new Uint8Array(totalTiles);
	const adjToLandCache = new Uint8Array(totalTiles);
	let maxPlayerRegion = 0;
	let nonOceanTileCount = 0;

	const groupCount = new Uint16Array(NUM_TILE_GROUPS);
	const groupAdjCount = new Uint16Array(NUM_TILE_GROUPS);
	const groupRawId = new Uint16Array(NUM_TILE_GROUPS);
	const regionCount = new Uint16Array(NUM_TILE_GROUPS * MAX_LANDMASS_REGIONS);
	const regionAdjCount = new Uint16Array(NUM_TILE_GROUPS * MAX_LANDMASS_REGIONS);

	const mapScanScope = new profileScope("buildPlacementContext Map Scan");
	for (let y = 0; y < iHeight; y++) {
		for (let x = 0; x < iWidth; x++) {
			const idx = y * iWidth + x;

			// Inline terrain/biome/feature lookups to avoid allocating a TileClass object per tile.
			const terrain = GameplayMap.getTerrainType(x, y);
			const biome = GameplayMap.getBiomeType(x, y);
			const feature = GameplayMap.getFeatureType(x, y);
			const rawId = getTileClassId(terrain as number, biome as number, feature as number);
			const id = tileIdToIndex[rawId];

			if (terrain !== globals.g_OceanTerrain) nonOceanTileCount++;
			const adjToLand =
				terrain === globals.g_CoastTerrain &&
				biome === globals.g_MarineBiome &&
				GameplayMap.isAdjacentToLand(x, y);
			let regionId = GameplayMap.getLandmassRegionId(x, y);
			if (regionId == LandmassRegion.LANDMASS_REGION_NONE) {
				regionId = 0;
			}
			tileIdCache[idx] = id;
			regionIdCache[idx] = regionId;
			adjToLandCache[idx] = adjToLand ? 1 : 0;

			if (groupCount[id] === 0) {
				groupRawId[id] = rawId;
			}
			groupCount[id]++;
			if (adjToLand) groupAdjCount[id]++;

			if (regionId > maxPlayerRegion) maxPlayerRegion = regionId;
			const rcKey = (id << LANDMASS_BIT_SHIFT) | regionId;

			regionCount[rcKey]++;
			if (adjToLand) regionAdjCount[rcKey]++;
		}
	}
	mapScanScope.end();

	const landmassEligibleScope = new profileScope("buildPlacementContext Landmass Eligibility");
	// For each player region, accumulate eligible tile counts per (tileGroupId, landmassGroup).
	const landmassEligible = new Map<number, { count: number; adj: number }>();
	for (let r = 0; r <= maxPlayerRegion; r++) {
		for (let i = 0; i < groupCount.length; ++i) {
			if (groupCount[i] === 0) continue;
			const tileId = i;
			const rcKey = (tileId << LANDMASS_BIT_SHIFT) | r;
			const rcCount = regionCount[rcKey];
			if (rcCount === 0) continue;
			const rcAdj = regionAdjCount[rcKey];
			for (let group = 1; group <= NUM_LANDMASS_GROUPS; group++) {
				if (r > 0 && !isResourceAllowedOnLandmass(group, r, NUM_LANDMASS_GROUPS)) continue;
				const hKey = getLandmassTileClassGroupId(tileId, group);
				const existing = landmassEligible.get(hKey);
				if (existing) {
					existing.count += rcCount;
					existing.adj += rcAdj;
				} else {
					landmassEligible.set(hKey, { count: rcCount, adj: rcAdj });
				}
			}
		}
	}
	landmassEligibleScope.end();

	return {
		iWidth,
		iHeight,
		groupCount,
		groupAdjCount,
		groupRawId,
		tileIdCache,
		regionIdCache,
		adjToLandCache,
		maxPlayerRegion,
		nonOceanTileCount,
		regionCount,
		regionAdjCount,
		landmassEligible,
	};
}

// ===========================================================================================
// Biome resolution
// ===========================================================================================

/**
 * Builds a ResourceSet from a list of candidate resources: filters to Tradeable,
 * assigns landmass groups to LandmassUnique resources via shuffled alternation
 * across NUM_LANDMASS_GROUPS, and packs into the ResourceSet used by placement.
 * The optional 'include' predicate applies additional filtering.
 */
export function prepareResourceSet(
	candidateHashes: ResourceType[],
	include?: (info: ResourceDefinition) => boolean,
): ResourceSet {
	const resourceWeight = new Float32Array(GameInfo.Resources.length);
	const activeResources: { typeIdx: number; landmassId: number }[] = [];

	for (const r of candidateHashes) {
		const info = GameInfo.Resources.lookup(r);
		if (!info || !info.Tradeable) continue;
		if (include && !include(info)) continue;
		resourceWeight[info.$index] = info.Weight;
		activeResources.push({ typeIdx: info.$index, landmassId: 0 });
	}

	// Shuffle LandmassUnique resources, then alternate 1..NUM_LANDMASS_GROUPS
	// so each game gets a different hemisphere split.
	const landmassResources = activeResources.filter((r) => GameInfo.Resources[r.typeIdx]?.LandmassUnique);
	for (let i = landmassResources.length - 1; i > 0; i--) {
		const j = TerrainBuilder.getRandomNumber(i + 1, "Landmass Shuffle");
		[landmassResources[i], landmassResources[j]] = [landmassResources[j], landmassResources[i]];
	}
	for (let i = 0; i < landmassResources.length; i++) {
		landmassResources[i].landmassId = (i % NUM_LANDMASS_GROUPS) + 1;
	}

	return buildResourceSet(activeResources, resourceWeight);
}

export interface ResolvedValidBiome {
	tileGroupId: number;
	resourceIdx: ResourceIndex;
	adjacentToLand: boolean;
	weight: number;
}

// Bundles the per-run resource inputs: which resources are active, their weights,
// their landmass assignments, and resolved biome/terrain/feature mappings.
export function buildResourceSet(
	activeResources: { typeIdx: number; landmassId: number }[],
	resourceWeight: Float32Array,
): ResourceSet {
	const numResources = GameInfo.Resources.length;

	const resourceAssignedLandmass = new Uint8Array(numResources);
	const activeResourceIndices = new Uint16Array(activeResources.length);
	const typeStrings = new Set<string>();
	for (let i = 0; i < activeResources.length; i++) {
		const r = activeResources[i];
		resourceAssignedLandmass[r.typeIdx] = r.landmassId;
		activeResourceIndices[i] = r.typeIdx;
		const def = GameInfo.Resources[r.typeIdx];
		if (def) typeStrings.add(def.ResourceType);
	}

	const resolvedValidBiomes: ResolvedValidBiome[] = [];
	for (const validBiome of GameInfo.Resource_ValidBiomes) {
		if (!typeStrings.has(validBiome.ResourceType)) continue;
		const resourceDef = GameInfo.Resources.find((r) => r.ResourceType === validBiome.ResourceType);
		if (!resourceDef) continue;
		const rawId = tileClassIdFromValidBiome(validBiome);
		if (rawId === undefined) continue;
		const tileGroupId = tileIdToIndex[rawId];
		const weight = validBiome.Weight ?? resourceWeight[resourceDef.$index];
		resolvedValidBiomes.push({
			tileGroupId,
			resourceIdx: resourceDef.$index,
			adjacentToLand: resourceDef.AdjacentToLand,
			weight,
		});
	}

	return { activeResourceIndices, resourceWeight, resourceAssignedLandmass, resolvedValidBiomes };
}

/**
 * Calculates blue noise placement windows for each tile group.
 *
 * For each tile group, competing resources share the density budget proportional to
 * their weight. Windows are packed into [0, 65535] for the placement pass.
 */
export function buildBlueNoiseWindows(
	ctx: ResourcePlacementContext,
	set: ResourceSet,
	config: DensityConfig,
): BlueNoisePlan {
	const BLUE_NOISE_RANGE = 65536;
	const { densityTarget, maxDensity } = config;

	const resourceEligibleTileCounts = new Uint32Array(GameInfo.Resources.length);
	const resourceEligiblePerLandmass = new Uint32Array(GameInfo.Resources.length * ctx.maxPlayerRegion);

	const tileGroupResources = new Map<
		number,
		{ resourceIdx: ResourceIndex; weight: number; density: number; windowSize: number; adjacentToLand: boolean }[]
	>();

	for (const entry of set.resolvedValidBiomes) {
		const groupCount = ctx.groupCount[entry.tileGroupId];
		if (groupCount === 0) continue;

		// Accumulate eligible tile counts.
		const assignedLandmass = set.resourceAssignedLandmass[entry.resourceIdx];
		let count: number;
		let adjCount: number;
		if (assignedLandmass === 0) {
			count = groupCount;
			adjCount = ctx.groupAdjCount[entry.tileGroupId];
		} else {
			const he = ctx.landmassEligible.get(getLandmassTileClassGroupId(entry.tileGroupId, assignedLandmass));
			count = he?.count ?? 0;
			adjCount = he?.adj ?? 0;
		}
		const eligible = entry.adjacentToLand ? adjCount : count;
		resourceEligibleTileCounts[entry.resourceIdx] += eligible;

		for (let regionId = 1; regionId <= ctx.maxPlayerRegion; regionId++) {
			if (!isResourceAllowedOnLandmass(assignedLandmass, regionId, NUM_LANDMASS_GROUPS)) continue;
			const rcKey = (entry.tileGroupId << LANDMASS_BIT_SHIFT) | regionId;
			const rcCount = ctx.regionCount[rcKey];
			if (rcCount === 0) continue;
			const rcAdj = ctx.regionAdjCount[rcKey];
			const tiles = entry.adjacentToLand ? rcAdj : rcCount;
			resourceEligiblePerLandmass[entry.resourceIdx * ctx.maxPlayerRegion + (regionId - 1)] += tiles;
		}

		// Build tileGroupResources entry (skip zero-weight resources).
		const weight = entry.weight;
		if (weight <= 0) continue;
		if (!tileGroupResources.has(entry.tileGroupId)) {
			tileGroupResources.set(entry.tileGroupId, []);
		}
		tileGroupResources.get(entry.tileGroupId)!.push({
			resourceIdx: entry.resourceIdx,
			weight,
			density: 0,
			windowSize: 0,
			adjacentToLand: entry.adjacentToLand,
		});
	}

	// Distribute density budget within each tile group by weight.
	if (config.densityByResourceAndGroup) {
		for (const [groupId, resources] of tileGroupResources) {
			for (const r of resources) {
				const key = r.resourceIdx * NUM_TILE_GROUPS + groupId;
				r.density = config.densityByResourceAndGroup[key];
			}
		}
	} else {
		for (const [, resources] of tileGroupResources) {
			for (const r of resources) {
				r.density = densityTarget * (r.weight / resources.length);
			}
		}
	}

	// Accumulate expected placement counts per resource.
	const resourceDesiredCount = new Float32Array(GameInfo.Resources.length);
	for (const [groupId, resources] of tileGroupResources) {
		const groupCount = ctx.groupCount[groupId];
		if (groupCount === 0) continue;
		for (const r of resources) {
			const assignedLandmass = set.resourceAssignedLandmass[r.resourceIdx];
			let effectiveTiles: number;
			if (assignedLandmass === 0) {
				effectiveTiles = r.adjacentToLand ? ctx.groupAdjCount[groupId] : groupCount;
			} else {
				const he = ctx.landmassEligible.get(getLandmassTileClassGroupId(groupId, assignedLandmass));
				effectiveTiles = r.adjacentToLand ? (he?.adj ?? 0) : (he?.count ?? 0);
			}
			resourceDesiredCount[r.resourceIdx] += r.density * effectiveTiles;
		}
	}

	// Enforce MinimumPerLandmass: scale up density if expected count is too low.
	const resourceMinimumPerLandmass = new Uint8Array(GameInfo.Resources.length);
	for (const resIdx of set.activeResourceIndices) {
		const def = GameInfo.Resources[resIdx];
		if (!def) continue;
		const minimum = config.effectiveMinimums ? config.effectiveMinimums[def.$index] : def.MinimumPerLandmass;
		if (minimum <= 0) continue;
		resourceMinimumPerLandmass[def.$index] = minimum;

		// Consider the minimum per landmass and how many landmasses are eligible for this resource.
		let numLandmassesEligible = 0;
		for (let r = 1; r <= ctx.maxPlayerRegion; r++) {
			if (resourceEligiblePerLandmass[def.$index * ctx.maxPlayerRegion + (r - 1)] > 0) {
				numLandmassesEligible++;
			}
		}
		if (numLandmassesEligible === 0) continue;

		const effectiveMin = minimum * numLandmassesEligible;
		const desired = resourceDesiredCount[def.$index];
		if (desired >= effectiveMin || desired <= 0) continue;

		resourceDesiredCount[def.$index] = effectiveMin;
		const scaleFactor = effectiveMin / desired;
		for (const [, resources] of tileGroupResources) {
			for (const rr of resources) {
				if (rr.resourceIdx === def.$index) {
					rr.density = rr.density * scaleFactor;
				}
			}
		}
	}

	// Build blue noise windows into flat typed arrays for interpreter performance.
	// First pass: count total windows to size the arrays.
	const windowOffsets = new Uint16Array(NUM_TILE_GROUPS);
	const windowCounts = new Uint8Array(NUM_TILE_GROUPS);
	let totalWindows = 0;

	for (const [key, resources] of tileGroupResources) {
		let cursor = 0;
		let count = 0;
		for (const r of resources) {
			r.windowSize = Math.round(Math.min(r.density, maxDensity) * BLUE_NOISE_RANGE);
			r.windowSize = Math.min(r.windowSize, BLUE_NOISE_RANGE - cursor);
			if (r.windowSize <= 0) continue;
			count++;
			cursor += r.windowSize;
			if (cursor >= BLUE_NOISE_RANGE) break;
		}
		windowOffsets[key] = totalWindows;
		windowCounts[key] = count;
		totalWindows += count;
	}

	// Second pass: fill packed arrays.
	const windowTypes = new Uint16Array(totalWindows);
	const windowSizes = new Uint16Array(totalWindows);
	const maxGapSize = new Uint16Array(NUM_TILE_GROUPS);

	for (const [key, resources] of tileGroupResources) {
		let cursor = 0;
		let wi = windowOffsets[key];
		for (const r of resources) {
			if (r.windowSize <= 0) continue;
			windowTypes[wi] = r.resourceIdx | (r.adjacentToLand ? ADJACENT_TO_LAND_FLAG : 0);
			windowSizes[wi] = r.windowSize;
			wi++;
			cursor += r.windowSize;
			if (cursor >= BLUE_NOISE_RANGE) break;
		}
		maxGapSize[key] = windowCounts[key] > 0 ? Math.floor((65535 - cursor) / windowCounts[key]) : 0;
	}

	if (VERBOSE_LOGGING) {
		console.log("Blue noise windows per tile group:");
		for (let key = 0; key < ctx.groupCount.length; key++) {
			const count = windowCounts[key];
			if (count === 0) continue;
			const tileClass: TileClass = tileClassFromId(ctx.groupRawId[key]);
			const label = tileClassLabel(tileClass);
			const offset = windowOffsets[key];
			for (let i = 0; i < count; i++) {
				const resourceIdx = windowTypes[offset + i] & RESOURCE_TYPE_MASK;
				const size = windowSizes[offset + i];
				const resName = GameInfo.Resources[resourceIdx]?.ResourceType ?? `Unknown(${resourceIdx})`;
				console.log(`  ${label}: ${resName} size=${size}`);
			}
		}
	}

	const windows: PackedBlueNoiseWindows = {
		types: windowTypes,
		sizes: windowSizes,
		offsets: windowOffsets,
		counts: windowCounts,
		maxGapSize: maxGapSize,
	};

	const metrics: ResourceMetrics = {
		resourceDesiredCount,
		resourceEligibleTileCounts,
		resourceEligiblePerLandmass,
		resourceMinimumPerLandmass,
	};

	return {
		windows,
		metrics,
	};
}

/**
 * Iterates every tile, samples blue noise, and places the resource whose window matches.
 *
 * Window sizes are scaled during placement to account for how far off we are from the expected count
 * to help ensure final counts are close to the desired density. If a resource ever falls behind in its
 * expected minimum count it is force-placed on the next eligible tile.
 */
export function placeResourcesWithBlueNoise(
	ctx: ResourcePlacementContext,
	set: ResourceSet,
	plan: BlueNoisePlan,
	options: PlacementOptions,
): void {
	const { iWidth, iHeight, tileIdCache, regionIdCache, adjToLandCache, maxPlayerRegion } = ctx;
	const { types: wTypes, sizes: wSizes, offsets: wOffsets, counts: wCounts, maxGapSize: wMaxGapSize } = plan.windows;

	// Hoist optional function refs once (avoids re-reading options object per tile).
	const skipMask = options.skipMask;
	const shouldPlaceResource = options.shouldPlaceResource;
	const onResourcePlaced = options.onResourcePlaced;
	const ox = options.offsetX;
	const oy = options.offsetY;

	const hitCounts = new Uint32Array(GameInfo.Resources.length);
	const regionHits = VERBOSE_LOGGING ? new Map<number, number>() : undefined;
	const numResources = GameInfo.Resources.length;
	const placedPerLandmass = new Uint16Array(numResources * maxPlayerRegion);
	const consideredPerLandmass = new Uint32Array(numResources * maxPlayerRegion);
	const resourceMinimumPerLandmass = plan.metrics.resourceMinimumPerLandmass;
	const forcePlacedHits = VERBOSE_LOGGING ? new Uint8Array(numResources * maxPlayerRegion) : undefined;

	const considered = new Uint32Array(GameInfo.Resources.length); // Eligible-tile tally per resource, used by the deficit multiplier.

	const GAP_FACTOR = 0.15; // Fraction of the max gap size to use as a minimum spacing between windows. 0 = even blue noise distribution, 1 = max spacing causing more "clumping" of resources.
	const GAIN = 2.0; // How quickly to adjust the multiplier based on how far off we are from the expected count.
	const M_MAX = 4.0; // Maximum multiplier to prevent runaway growth of a single resource type.
	const MAX_REGION_COUNT = 256; // ctx.regionIdCache is 8 bits
	const maxMultiplier = new Float32Array(GameInfo.Resources.length).fill(1.0);
	const minMultiplier = new Float32Array(GameInfo.Resources.length).fill(1.0);

	let deniedByCanHaveResource = 0;

	// Applies the placement, updates hit/region/landmass counters, and returns false if the veto hook rejects.
	const placeResource = (
		x: number,
		y: number,
		resourceIdx: ResourceIndex,
		regionId: number,
		forced = false,
	): boolean => {
		// Let caller veto this specific placement.
		if (shouldPlaceResource?.(x, y, resourceIdx, regionId) === false) return false;
		if (!ResourceBuilder.canHaveResource(x, y, resourceIdx, true)) {
			++deniedByCanHaveResource;
			return false;
		}

		ResourceBuilder.setResourceType(x, y, resourceIdx);
		hitCounts[resourceIdx]++;

		const k = resourceIdx * maxPlayerRegion + (regionId - 1);
		if (regionId > 0) {
			placedPerLandmass[k]++;
		}

		if (VERBOSE_LOGGING) {
			const rKey = resourceIdx * MAX_REGION_COUNT + regionId;
			regionHits!.set(rKey, (regionHits!.get(rKey) ?? 0) + 1);
			if (forced && regionId > 0) {
				forcePlacedHits![k]++;
			}
		}
		onResourcePlaced?.(x, y, resourceIdx, regionId);
		return true;
	};

	// 2x2 checkerboard pass order so the adaptive multiplier doesn't systematically bias one region.
	for (let pass = 0; pass < 4; ++pass) {
		const xStart = pass & 1;
		const yStart = (pass >> 1) & 1;
		for (let y = yStart; y < iHeight; y += 2) {
			for (let x = xStart; x < iWidth; x += 2) {
				const idx = y * iWidth + x;

				if (skipMask && skipMask[idx]) continue;

				const tileGroup = tileIdCache[idx];
				const count = wCounts[tileGroup];
				if (count === 0) continue;

				const offset = wOffsets[tileGroup];
				const adjToLand = adjToLandCache[idx] === 1;
				const regionId = regionIdCache[idx];
				const isPlayerLandmass = regionId > 0 && regionId <= maxPlayerRegion;

				// First pass over this tile's candidate resources: tally eligibility and pick a force-place target if any resource is behind its minimum.
				let forcePlaceIdx = -1;
				for (let i = 0; i < count; i++) {
					const packed = wTypes[offset + i];
					if (packed & ADJACENT_TO_LAND_FLAG && !adjToLand) continue;
					const resourceIdx = packed & RESOURCE_TYPE_MASK;
					// Check landmass eligibility for landmass-specific resources.
					if (
						!isResourceAllowedOnLandmass(
							set.resourceAssignedLandmass[resourceIdx],
							regionId,
							NUM_LANDMASS_GROUPS,
						)
					)
						continue;

					// Track the number of potential placements of this resource globally and per landmass.
					considered[resourceIdx]++;
					if (isPlayerLandmass) {
						const k = resourceIdx * maxPlayerRegion + (regionId - 1);
						consideredPerLandmass[k]++;

						// If this resource has a minimum per landmass and we haven't placed enough yet, mark it for forced placement.
						if (forcePlaceIdx === -1) {
							const min = resourceMinimumPerLandmass[resourceIdx];
							if (min > 0) {
								const placed = placedPerLandmass[k];
								if (placed < min) {
									const eligibleLandmass = plan.metrics.resourceEligiblePerLandmass[k];
									if (eligibleLandmass > 0) {
										// Consider how many are likely to get placed naturally compared to how many need to be placed to meet the minimum.
										// If we are likely to fall short, force place this resource.
										const eligibleTotal = plan.metrics.resourceEligibleTileCounts[resourceIdx];
										const desiredTotal = plan.metrics.resourceDesiredCount[resourceIdx];
										const naturalRate = desiredTotal / eligibleTotal;
										const remainingLandmass = eligibleLandmass - consideredPerLandmass[k];
										const expectedNatural = naturalRate * remainingLandmass;

										if (placed + expectedNatural < min - 0.5) {
											forcePlaceIdx = resourceIdx;
										}
									}
								}
							}
						}
					}
				}

				if (forcePlaceIdx !== -1) {
					// Force place a resource here and skip normal placement.
					if (placeResource(x, y, forcePlaceIdx, regionId, true)) continue;
				}

				const noiseVal = sampleBlueNoise(x + ox, y + oy);
				const maxGap = wMaxGapSize[tileGroup];
				const gapSize = maxGap * GAP_FACTOR;

				let remaining = noiseVal;
				for (let wi = 0; wi < count; wi++) {
					if (remaining < gapSize) break;
					remaining -= gapSize;

					const wSize = wSizes[offset + wi];
					const packed = wTypes[offset + wi];
					const resourceIdx = packed & RESOURCE_TYPE_MASK;

					// Adjust window size based on the deficit/excess of this resource type relative to its expected count.
					let m = 1.0;
					const desired = plan.metrics.resourceDesiredCount[resourceIdx];
					const totalEligible = plan.metrics.resourceEligibleTileCounts[resourceIdx];
					if (desired > 0 && totalEligible > 0) {
						// Compare hits so far vs. the expected count, given how many tiles we've scanned.
						// Scale this resource's window by (1 + GAIN * deficit / desired), clamped to [0, M_MAX].
						const expected = (desired * considered[resourceIdx]) / totalEligible;
						const deficit = expected - hitCounts[resourceIdx];
						m = 1 + (GAIN * deficit) / desired;
						if (m < 0) m = 0;
						else if (m > M_MAX) m = M_MAX;
						if (VERBOSE_LOGGING) {
							if (m > maxMultiplier[resourceIdx]) maxMultiplier[resourceIdx] = m;
							if (m < minMultiplier[resourceIdx]) minMultiplier[resourceIdx] = m;
						}
					}

					const adjSize = Math.min((wSize * m) | 0, wSize + maxGap);
					if (remaining < adjSize) {
						// Skip if this resource requires land adjacency and the tile doesn't qualify.
						if (packed & ADJACENT_TO_LAND_FLAG && !adjToLand) break;

						// Check landmass eligibility for landmass-specific resources.
						if (
							!isResourceAllowedOnLandmass(
								set.resourceAssignedLandmass[resourceIdx],
								regionId,
								NUM_LANDMASS_GROUPS,
							)
						)
							break;

						placeResource(x, y, resourceIdx, regionId);
						break; // Only one resource per tile
					}
					remaining -= wSize;
				}
			}
		}
	}

	// Verbose placement summary.
	if (VERBOSE_LOGGING) {
		const resourceDesiredCount = plan.metrics.resourceDesiredCount;
		console.log("Blue noise placement results:");
		for (let resourceIdx = 0; resourceIdx < hitCounts.length; resourceIdx++) {
			const hitCount = hitCounts[resourceIdx];
			if (hitCount === 0) continue;
			const resName = GameInfo.Resources[resourceIdx]?.ResourceType ?? `Unknown(${resourceIdx})`;
			const desired = resourceDesiredCount[resourceIdx];
			const desiredLabel = desired !== undefined ? ` (desired: ${desired.toFixed(2)})` : "";
			const eligibleLabel = ` (eligible: ${plan.metrics.resourceEligibleTileCounts[resourceIdx] ?? 0})`;
			const landmass = set.resourceAssignedLandmass[resourceIdx];
			const landmassLabel = landmass > 0 ? ` [landmass ${landmass}]` : "";
			const regionParts: string[] = [];
			if (regionHits) {
				for (let r = 0; r <= maxPlayerRegion; r++) {
					const count = regionHits.get(resourceIdx * MAX_REGION_COUNT + r) ?? 0;
					if (count > 0) regionParts.push(`r${r}=${count}`);
				}
			}
			const regionSuffix = regionParts.length > 0 ? ` regions: (${regionParts.join(", ")})` : "";
			let forcedLabel = "";
			const forceParts: string[] = [];
			for (let r = 1; r <= maxPlayerRegion; r++) {
				const count = forcePlacedHits![resourceIdx * maxPlayerRegion + (r - 1)];
				if (count > 0) forceParts.push(`r${r}=${count}`);
			}
			forcedLabel =
				forceParts.length > 0
					? `\n    (force placed for min ${resourceMinimumPerLandmass[resourceIdx]}: ${forceParts.join(", ")})`
					: "";
			const minmaxMultipliersLabel = ` max/min multipliers: ${maxMultiplier[resourceIdx].toFixed(2)}/${minMultiplier[resourceIdx].toFixed(2)}`;
			console.log(
				`  ${resName}: ${hitCount} hits${desiredLabel}${eligibleLabel}${landmassLabel}${regionSuffix}${minmaxMultipliersLabel}${forcedLabel}`,
			);
		}
		console.log(`  Total denied by canHaveResource(): ${deniedByCanHaveResource}`);
		console.log(`Total resource blue noise hits: ${hitCounts.reduce((a, b) => a + b, 0)}`);
	}
}
